"""Dependency-free visual connector management surface."""

CONNECTOR_HTML = r'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Amodex Connections</title>
<style>
:root{color-scheme:dark;--bg:#0b0d10;--panel:#11151a;--card:#171c22;--line:#28313b;--text:#eef2f6;--muted:#8793a0;--accent:#80bfff;--good:#58d68d;--warn:#f0b35b;--bad:#ff6b6b;font-family:system-ui,-apple-system,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}button,input,select{font:inherit;color:inherit;background:#0d1116;border:1px solid var(--line);border-radius:10px;padding:9px 11px}button{cursor:pointer}.shell{max-width:1120px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:14px;margin-top:18px}.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px}.resource{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:11px;margin:8px 0}.muted{color:var(--muted);font-size:.84rem}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.grow{flex:1}.good{color:var(--good)}.warn{color:var(--warn)}.bad{color:var(--bad)}select,input{width:100%}.provider{font-weight:800;font-size:1.08rem}.pill{border:1px solid var(--line);border-radius:999px;padding:4px 7px;font-size:.75rem}.error{position:fixed;right:14px;bottom:14px;max-width:420px;padding:12px;background:#3a1717;border:1px solid var(--bad);border-radius:10px;display:none}h1{margin:.2rem 0}h2{font-size:1rem;margin:0 0 10px}@media(max-width:600px){.shell{padding:10px}.grid{grid-template-columns:1fr}.top button{padding:8px}}
</style></head><body><main class="shell">
<div class="top"><div><h1>Connections & Resources</h1><div class="muted">GitHub App + Roblox Open Cloud · tokens permanecem fora do PostgreSQL</div></div><button onclick="location.href='/'">← Voltar ao Workspace</button></div>
<div class="card" style="margin-top:16px"><div class="row"><div class="grow"><strong>Project Workspace</strong><select id="workspace" onchange="loadWorkspace()"></select></div><div class="grow"><strong>Environment para vínculo</strong><select id="environment"><option value="">Nenhum</option></select></div></div></div>
<div class="grid"><section class="card"><div class="row"><span class="provider">GitHub</span><span id="githubStatus" class="pill">…</span></div><p class="muted">Conecte o GitHub App, escolha quais repositórios o app pode acessar e atualize a lista abaixo.</p><div class="row"><button id="githubConnect" onclick="start('github')">Conectar GitHub</button><button onclick="refreshProvider('GITHUB')">Atualizar recursos</button></div><div id="githubAccounts"></div></section>
<section class="card"><div class="row"><span class="provider">Roblox</span><span id="robloxStatus" class="pill">…</span></div><p class="muted">OAuth do Open Cloud. Universes autorizados aparecem como Resources; Places podem ser validados pelos IDs.</p><div class="row"><button id="robloxConnect" onclick="start('roblox')">Conectar Roblox</button><button onclick="refreshProvider('ROBLOX')">Atualizar recursos</button></div><div id="robloxAccounts"></div></section></div>
<section class="card" style="margin-top:14px"><h2>Resources</h2><div id="resources" class="muted">Selecione um Workspace.</div></section>
</main><div id="error" class="error"></div>
<script>
const state={workspaces:[],workspace:null,envs:[],statuses:[],accounts:[],resources:[]};const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,o={}){const r=await fetch(p,{headers:{'content-type':'application/json',...(o.headers||{})},...o});let b=null;try{b=await r.json()}catch{}if(!r.ok){const d=b?.detail;throw new Error(d?.message||d?.code||(typeof d==='string'?d:null)||r.statusText)}return b}function fail(e){error.textContent=e.message||e;error.style.display='block';setTimeout(()=>error.style.display='none',5000)}
async function boot(){try{const [ws,st]=await Promise.all([api('/v1/workspaces'),api('/v1/connectors/status')]);state.workspaces=ws;state.statuses=st;workspace.innerHTML=ws.map(w=>`<option value="${esc(w.workspace_id)}">${esc(w.name)}</option>`).join('')||'<option value="">Nenhum projeto</option>';renderStatus();if(ws.length)await loadWorkspace()}catch(e){fail(e)}}
function renderStatus(){for(const p of ['GITHUB','ROBLOX']){const s=state.statuses.find(x=>x.provider===p);const el=document.getElementById(p==='GITHUB'?'githubStatus':'robloxStatus');el.textContent=s?.state||'UNKNOWN';el.className='pill '+(s?.state==='READY'?'good':'warn');}}
async function loadWorkspace(){try{state.workspace=workspace.value;if(!state.workspace)return;[state.envs,state.accounts]=await Promise.all([api(`/v1/workspaces/${state.workspace}/environments`),api(`/v1/workspaces/${state.workspace}/connectors`)]);environment.innerHTML='<option value="">Nenhum</option>'+state.envs.map(x=>`<option value="${esc(x.environment_id)}">${esc(x.label||x.environment_id)}</option>`).join('');await loadResources();renderAccounts()}catch(e){fail(e)}}
async function start(provider){try{const x=await api(`/v1/workspaces/${state.workspace}/connectors/${provider}/start`,{method:'POST'});sessionStorage.setItem('amodex_install_url',x.installation_url||'');location.href=x.authorization_url}catch(e){fail(e)}}
async function refreshProvider(provider){try{const accounts=state.accounts.filter(a=>a.provider===provider&&a.state==='CONNECTED');for(const a of accounts)await api(`/v1/connectors/${a.connector_id}/refresh`,{method:'POST'});await loadWorkspace()}catch(e){fail(e)}}
async function loadResources(){state.resources=[];for(const a of state.accounts){if(a.state==='CONNECTED'){const r=await api(`/v1/connectors/${a.connector_id}/resources`);state.resources.push(...r)}}renderResources()}
function renderAccounts(){const render=p=>{const list=state.accounts.filter(a=>a.provider===p);return list.length?list.map(a=>`<div class="resource"><strong>${esc(a.external_account_name||a.external_account_id||'conta')}</strong><div class="muted">${esc(a.state)} · ${esc(a.connector_id)}</div><div class="row" style="margin-top:7px"><button onclick="disconnect('${esc(a.connector_id)}')">Desconectar</button>${p==='ROBLOX'&&a.state==='CONNECTED'?`<button onclick="addPlace('${esc(a.connector_id)}')">Adicionar Place</button>`:''}</div></div>`).join(''):'<div class="muted" style="margin-top:10px">Nenhuma conta conectada.</div>'};githubAccounts.innerHTML=render('GITHUB');robloxAccounts.innerHTML=render('ROBLOX')}
function renderResources(){resources.innerHTML=state.resources.length?state.resources.map(r=>`<div class="resource"><div class="row"><div class="grow"><strong>${esc(r.name)}</strong><div class="muted">${esc(r.resource_type)} · ${esc(r.external_id)}</div></div><span class="pill">${r.bound_environment_id?'vinculado':'livre'}</span></div><div class="row" style="margin-top:8px"><button onclick="bind('${esc(r.resource_id)}')">Vincular ao Environment selecionado</button>${r.url?`<button onclick="window.open('${esc(r.url)}','_blank')">Abrir</button>`:''}</div></div>`).join(''):'<div class="muted">Nenhum Resource sincronizado.</div>'}
async function bind(id){try{await api(`/v1/connector-resources/${id}/bind`,{method:'POST',body:JSON.stringify({environment_id:environment.value||null})});await loadWorkspace()}catch(e){fail(e)}}async function disconnect(id){try{await api(`/v1/connectors/${id}`,{method:'DELETE'});await loadWorkspace()}catch(e){fail(e)}}async function addPlace(id){const universe_id=prompt('Universe ID');if(!universe_id)return;const place_id=prompt('Place ID');if(!place_id)return;try{await api(`/v1/connectors/${id}/roblox/places`,{method:'POST',body:JSON.stringify({universe_id,place_id})});await loadWorkspace()}catch(e){fail(e)}}
boot();
</script></body></html>'''
